COMMENT ON TABLE "care_delivery_program_masters" IS 'EXISTING. The tenant boundary (CDP).';

COMMENT ON TABLE "corp_masters" IS 'EXISTING. A corporate/employer entity inside a CDP.';

COMMENT ON TABLE "employee_masters" IS 'EXISTING. No direct CDP column — tenant is reached via corp_masters.';

COMMENT ON COLUMN "employee_masters"."reporting_manager_id" IS 'approval chain';

COMMENT ON TABLE "users" IS 'EXISTING. Login identity; audit columns point here.';

COMMENT ON TABLE "status_masters" IS 'EXISTING. Reused instead of new per-domain status tables.';

COMMENT ON COLUMN "status_masters"."source_activity" IS 'attendance | attendance_request | leave_request';

COMMENT ON TABLE "care_delivery_program_parameter_details" IS 'EXISTING. Holds tenant policy knobs: regularization window days, auto-absent days, leave-year start month.';

COMMENT ON TABLE "address_details" IS 'EXISTING polymorphic. No DB FK — join on the (type, id) pair. Holds work-location addresses.';

COMMENT ON COLUMN "address_details"."addressable_type" IS 'WorkLocationMaster';

COMMENT ON TABLE "image_details" IS 'EXISTING polymorphic. No DB FK. Holds request attachments and medical certificates.';

COMMENT ON COLUMN "image_details"."imageable_type" IS 'AttendanceRequestDetail | LeaveRequestDetail';

COMMENT ON TABLE "work_location_masters" IS 'Branch / office / site. Address lives in address_details via the polymorphic pair.';

COMMENT ON COLUMN "work_location_masters"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON TABLE "shift_masters" IS 'First use of the `time` type in this codebase.';

COMMENT ON COLUMN "shift_masters"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "shift_masters"."start_time" IS 'clock face at the work location, not UTC';

COMMENT ON COLUMN "shift_masters"."is_night_shift" IS 'crosses midnight';

COMMENT ON COLUMN "shift_week_off_details"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "shift_week_off_details"."day_of_week" IS 'ISO 1=Mon .. 7=Sun';

COMMENT ON COLUMN "shift_week_off_details"."week_of_month" IS 'NULL = every week. 2 and 4 + Saturday = alternate-Saturday rule';

COMMENT ON COLUMN "holiday_calendar_masters"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "holiday_calendar_masters"."work_location_master_id" IS 'NULL = all locations';

COMMENT ON COLUMN "holiday_details"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "holiday_details"."holiday_type" IS 'Public | Restricted | Optional';

COMMENT ON TABLE "employee_shift_details" IS 'Standing assignment. Rotating rosters = successive dated rows, so no per-day roster table.';

COMMENT ON COLUMN "employee_shift_details"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "employee_shift_details"."trmntn_dt" IS 'NULL = current assignment';

COMMENT ON COLUMN "attendance_device_masters"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "attendance_device_masters"."vendor" IS 'ZKTeco | eSSL | Realtime | Matrix | Generic';

COMMENT ON COLUMN "attendance_device_masters"."protocol" IS 'ADMS_PUSH | REST';

COMMENT ON COLUMN "attendance_device_masters"."status" IS 'Active | Inactive | Unreachable';

COMMENT ON TABLE "employee_device_mappings" IS 'Biometric enrollment numbers are NOT emp_id. Unique index uses NULLS NOT DISTINCT (PG 15+).';

COMMENT ON COLUMN "employee_device_mappings"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "employee_device_mappings"."attendance_device_master_id" IS 'NULL = valid on every device in the tenant';

COMMENT ON TABLE "attendance_punch_details" IS 'APPEND-ONLY. The canonical AttendanceEvent. The 4-column unique index is the dedupe key from architecture-plan.md line 111.';

COMMENT ON COLUMN "attendance_punch_details"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "attendance_punch_details"."employee_master_id" IS 'NULL = unresolved punch';

COMMENT ON COLUMN "attendance_punch_details"."attendance_device_master_id" IS 'NULL = app punch';

COMMENT ON COLUMN "attendance_punch_details"."device_serial" IS 'raw, kept for punches from unregistered devices';

COMMENT ON COLUMN "attendance_punch_details"."punch_at" IS 'UTC';

COMMENT ON COLUMN "attendance_punch_details"."punch_source" IS 'Biometric | Web | Mobile | Manual | Import';

COMMENT ON COLUMN "attendance_punch_details"."direction" IS 'IN | OUT. NULL for auto-direction devices';

COMMENT ON COLUMN "attendance_punch_details"."employee_attendance_detail_id" IS 'set by the assembler';

COMMENT ON COLUMN "attendance_punch_details"."created_by_id" IS 'nullable — device ingestion has no user';

COMMENT ON TABLE "employee_attendance_details" IS 'One row per employee per date — the table every report, payroll LOP run and UI grid reads. The unique constraint is what makes the nightly assembler idempotent. Deliberately has NO attendance_request_detail_id: that FK points the other way to avoid a circular dependency.';

COMMENT ON COLUMN "employee_attendance_details"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "employee_attendance_details"."attendance_date" IS 'local business date at the work location';

COMMENT ON COLUMN "employee_attendance_details"."day_type" IS 'Working | WeekOff | Holiday';

COMMENT ON COLUMN "employee_attendance_details"."attendance_status" IS 'Present | Absent | HalfDay | OnLeave | OnDuty | WFH | WeekOff | Holiday';

COMMENT ON COLUMN "employee_attendance_details"."shift_start_at" IS 'shift time resolved to an instant — disambiguates night shifts and DST';

COMMENT ON COLUMN "employee_attendance_details"."payable_day_fraction" IS '0.00 / 0.50 / 1.00 — the payroll LOP hand-off';

COMMENT ON COLUMN "employee_attendance_details"."source" IS 'Auto | Manual | Regularized | Import';

COMMENT ON COLUMN "employee_attendance_details"."is_locked" IS 'frozen once payroll runs';

COMMENT ON COLUMN "employee_attendance_details"."created_by_id" IS 'nullable — job-written';

COMMENT ON TABLE "attendance_request_details" IS 'One table for all correction flows, discriminated by request_type. Attachments via image_details.';

COMMENT ON COLUMN "attendance_request_details"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "attendance_request_details"."request_type" IS 'Regularization | OnDuty | WFH | ShortLeave';

COMMENT ON COLUMN "attendance_request_details"."status" IS 'Pending | Approved | Rejected | Cancelled';

COMMENT ON COLUMN "leave_type_masters"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "leave_type_masters"."code" IS 'CL | SL | EL | ML | LOP';

COMMENT ON COLUMN "leave_type_masters"."unit" IS 'Day | Hour';

COMMENT ON COLUMN "leave_type_masters"."gender_applicable" IS 'maternity / paternity gating';

COMMENT ON COLUMN "leave_type_masters"."applicable_after_days" IS 'probation gate';

COMMENT ON TABLE "leave_policy_details" IS 'Split from leave_type_masters because accrual varies by employee type / corp within one leave type.';

COMMENT ON COLUMN "leave_policy_details"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "leave_policy_details"."corp_master_id" IS 'NULL = all corps';

COMMENT ON COLUMN "leave_policy_details"."employee_type_master_id" IS 'master table not yet created';

COMMENT ON COLUMN "leave_policy_details"."accrual_frequency" IS 'Monthly | Quarterly | Yearly | OnJoining';

COMMENT ON COLUMN "leave_policy_details"."reset_month" IS '1-12, leave-year start';

COMMENT ON TABLE "leave_request_details" IS 'Medical certificates attach via image_details.';

COMMENT ON COLUMN "leave_request_details"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "leave_request_details"."from_half" IS 'FirstHalf | SecondHalf';

COMMENT ON COLUMN "leave_request_details"."status" IS 'Pending | Approved | Rejected | Cancelled';

COMMENT ON TABLE "leave_request_day_details" IS 'One row per calendar day. Makes the daily-attendance join a plain equi-join on (employee, date) and LOP arithmetic trivial.';

COMMENT ON COLUMN "leave_request_day_details"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "leave_request_day_details"."day_fraction" IS '1.00 or 0.50';

COMMENT ON TABLE "employee_leave_balance_ledgers" IS 'APPEND-ONLY. No archive columns, no UPDATE path — corrections are new Reversal rows pointing at reversal_of_id. Per architecture-plan.md line 160.';

COMMENT ON COLUMN "employee_leave_balance_ledgers"."care_delivery_program_master_id" IS 'tenant';

COMMENT ON COLUMN "employee_leave_balance_ledgers"."txn_type" IS 'Opening | Accrual | Availed | Reversal | CarryForward | Encashment | LapseExpiry | Adjustment';

COMMENT ON COLUMN "employee_leave_balance_ledgers"."quantity" IS 'signed: + credit, - debit';

COMMENT ON COLUMN "employee_leave_balance_ledgers"."balance_after" IS 'running snapshot for O(1) balance reads';

COMMENT ON COLUMN "employee_leave_balance_ledgers"."created_by_id" IS 'nullable — accrual job';

